Output865[Better Approach] Using Local Minima and Maxima - O(n) Time and O(1) SpaceThe idea is to traverse the array from left to right and Find local minima (where price starts rising) and then a local maxima (where price stops rising). Compute the difference between two and add to the result. Below is the implementation of the algorithm
            C++

    #include <iostream>
#include <vector>
using namespace std;

int maxProfit(vector<int>& prices) {
    int n = prices.size();

     // Local Minima
    int lMin = prices[0]; 

    // Local Maxima
    int lMax = prices[0];  
    int res = 0;

    int i = 0;
    while (i < n - 1) {

        // Find local minima 
        while (i < n - 1 && prices[i] >= prices[i + 1]) { i++; }
        lMin = prices[i];

        // Local Maxima
        while (i < n - 1 && prices[i] <= prices[i + 1]) { i++; }
        lMax = prices[i];

        // Add current profit 
        res = res + (lMax - lMin);
    }

    return res;
}

int main() {
    vector<int> prices = {100, 180, 260, 310, 40, 535, 695};
    cout << maxProfit(prices);
    return 0;
}


